sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below

   removeDefaultTextSelection();
   readOnlyFields();
}

function removeDefaultTextSelection() {
	var text = g_form.getValue('triage_note');
	if (text) {
		g_form.setValue('triage_note', '');
	}
	setTimeout(function() {
		var field = g_form.getControl('triage_note');
		var len = text.length;
		if (field && len > 0) {
			field.focus();
			g_form.setValue('triage_note', text);
		}
	}, 1);
}

function readOnlyFields() {
	g_form.setReadOnly('patient.number', true);
	if (g_form.getViewName() != 'new_visit') {
		g_form.setReadOnly('patient', true);
    }
}
